sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;

  // Load the catalog item widget
  spUtil.get('sc_cat_item', {
    sys_id: c.data.catalogItemId,
    hide_order_button: true
  }).then(function(response) {
    c.catalogWidget = response;
  });

  // Override the order button with Request Access
  c.submitRequest = function() {
    $scope.$broadcast('submit.catalog.item');
  };
};

sp_widget.css:
.sar-container {
  max-width: 860px !important;
  margin: 0 auto !important;
  padding: 24px !important;
}

.sar-header {
  margin-bottom: 24px !important;
}

.sar-title {
  font-size: 1.8rem !important;
  font-weight: 700 !important;
  color: #0F172A !important;
  margin-bottom: 6px !important;
}

.sar-desc {
  color: #64748B !important;
  font-size: 0.95rem !important;
}

/* Hide Order Now button and Quantity field */
.sar-embed .sc-order-now-btn,
.sar-embed [ng-click*="orderNow"],
.sar-embed .btn-checkout,
.sar-embed .quantity-selector,
.sar-embed .sc-quantity,
.sar-embed label[for*="quantity"],
.sar-embed .input-group-qty,
.sar-embed [class*="quantity"],
.sar-embed [class*="order-now"],
.sar-embed .order-now,
.sar-embed .sp-order-now {
  display: none !important;
}

/* Style Add to Cart button as Request Access */
.sar-embed .btn-cart,
.sar-embed [ng-click*="addToCart"],
.sar-embed .sc-cart-btn {
  background: #2563EB !important;
  color: #FFFFFF !important;
  border: none !important;
  border-radius: 999px !important;
  padding: 12px 32px !important;
  font-weight: 600 !important;
  font-size: 0.9rem !important;
  width: 100% !important;
  margin-top: 8px !important;
}

.sar-embed .btn-cart::after,
.sar-embed [ng-click*="addToCart"]::after {
  content: ' Access' !important;
}

sp_widget.script:
(function() {
    var gr = new GlideRecord('sc_cat_item');
    gr.addQuery('name', 'System Access Request');
    gr.query();
    if (gr.next()) {
        data.catalogItemId = gr.getUniqueValue();
    }
})();
